/*=============================================================================
  DQ_Framework_Config.sql
  Data Quality Framework - Step 4: Framework Schema, Tables & Config Load
  Database: BANKING_DQ_DB | Schema: DQ_MONITORING
  
  Objects Created:
    - Schema: DQ_MONITORING
    - Tables: DQ_RULE_CONFIG, DQ_RUN_CONTROL, DQ_RULE_RESULTS,
              DQ_ERROR_RECORDS, DQ_ANOMALY_RESULTS
    - Data:   61 rules loaded into DQ_RULE_CONFIG (all plain SQL)
  
  RULE_SQL CONVENTION:
    Every RULE_SQL is a complete, executable SELECT returning a single NUMBER.
    - Violation rules return COUNT of bad rows (0 = pass)
    - ROW_COUNT rules return total rows (always pass, used for anomaly detection)
    No DMF function calls — all plain SQL for portability and debuggability.
=============================================================================*/

-- ============================================================================
-- PART 1: CREATE SCHEMA
-- ============================================================================
CREATE SCHEMA IF NOT EXISTS BANKING_DQ_DB.DQ_MONITORING;

-- ============================================================================
-- PART 2: CREATE FRAMEWORK TABLES
-- ============================================================================

-- 2.1 DQ_RULE_CONFIG: Stores all data quality rule definitions
CREATE OR REPLACE TABLE BANKING_DQ_DB.DQ_MONITORING.DQ_RULE_CONFIG (
    RULE_ID        VARCHAR(50) NOT NULL,
    RULE_NAME      VARCHAR(200) NOT NULL,
    RULE_TYPE      VARCHAR(50) NOT NULL,
    FREQUENCY      VARCHAR(50) DEFAULT 'TRIGGER_ON_CHANGES',
    CRITICALITY    VARCHAR(20) NOT NULL,
    DB_NAME        VARCHAR(200) NOT NULL,
    TABLE_NM       VARCHAR(200) NOT NULL,
    COLUMN_NM      VARCHAR(200),
    RULE_DESCRIPTION VARCHAR(1000),
    RULE_SQL       VARCHAR(4000),
    THRESHOLD_VALUE NUMBER(18,4) DEFAULT 0,
    RULE_DIMENSION VARIANT,
    IS_ACTIVE      BOOLEAN DEFAULT TRUE,
    CREATED_AT     TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),
    UPDATED_AT     TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- 2.2 DQ_RUN_CONTROL: Tracks each execution run
CREATE OR REPLACE TABLE BANKING_DQ_DB.DQ_MONITORING.DQ_RUN_CONTROL (
    RUN_ID           VARCHAR(50) NOT NULL,
    RULE_ID          VARCHAR(50) NOT NULL,
    RUN_START_TIME   TIMESTAMP_NTZ,
    RUN_END_TIME     TIMESTAMP_NTZ,
    RULE_EXEC_RESULT VARCHAR(20),
    RULE_OUTPUT_VALUE NUMBER(18,4),
    RUN_STATUS       VARCHAR(20) DEFAULT 'PENDING',
    TRIGGERED_BY     VARCHAR(100) DEFAULT 'MANUAL',
    ERROR_MESSAGE    VARCHAR(2000),
    CREATED_AT       TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),
    UPDATED_AT       TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- 2.3 DQ_RULE_RESULTS: Stores rule-level execution results
CREATE OR REPLACE TABLE BANKING_DQ_DB.DQ_MONITORING.DQ_RULE_RESULTS (
    RESULT_ID          VARCHAR(50) NOT NULL,
    RUN_ID             VARCHAR(50) NOT NULL,
    RULE_ID            VARCHAR(50) NOT NULL,
    DB_NAME            VARCHAR(200),
    TABLE_NAME         VARCHAR(200),
    COLUMN_NAME        VARCHAR(200),
    RULE_NAME          VARCHAR(200),
    RULE_TYPE          VARCHAR(50),
    EXPECTED_VALUE     NUMBER(18,4),
    ACTUAL_VALUE       NUMBER(18,4),
    FAILED_RECORD_COUNT NUMBER(18,0),
    TOTAL_RECORD_COUNT  NUMBER(18,0),
    PASS_PERCENTAGE    NUMBER(7,2),
    RESULT_STATUS      VARCHAR(20),
    SEVERITY           VARCHAR(20),
    ERROR_SAMPLE_QUERY VARCHAR(4000),
    EXECUTED_AT        TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- 2.4 DQ_ERROR_RECORDS: Stores detailed failed/sample records
CREATE OR REPLACE TABLE BANKING_DQ_DB.DQ_MONITORING.DQ_ERROR_RECORDS (
    ERROR_ID             VARCHAR(50) NOT NULL,
    RUN_ID               VARCHAR(50) NOT NULL,
    RULE_ID              VARCHAR(50) NOT NULL,
    DB_NAME              VARCHAR(200),
    TABLE_NAME           VARCHAR(200),
    ERROR_RECORD_VARIANT VARIANT,
    ERROR_REASON         VARCHAR(1000),
    CREATED_AT           TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- 2.5 DQ_ANOMALY_RESULTS: Stores anomaly detection results
CREATE OR REPLACE TABLE BANKING_DQ_DB.DQ_MONITORING.DQ_ANOMALY_RESULTS (
    ANOMALY_ID       VARCHAR(50) NOT NULL,
    RUN_ID           VARCHAR(50) NOT NULL,
    DATABASE_NAME    VARCHAR(200),
    SCHEMA_NAME      VARCHAR(200),
    TABLE_NAME       VARCHAR(200),
    METRIC_NAME      VARCHAR(200),
    CURRENT_VALUE    NUMBER(18,4),
    PREVIOUS_VALUE   NUMBER(18,4),
    BASELINE_AVG     NUMBER(18,4),
    BASELINE_STDDEV  NUMBER(18,4),
    ANOMALY_STATUS   VARCHAR(50),
    ANOMALY_REASON   VARCHAR(1000),
    DETECTED_AT      TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- ============================================================================
-- PART 3: LOAD RULES INTO DQ_RULE_CONFIG (all plain SQL)
-- ============================================================================

-- 3.1 BRANCHES rules (8 rules)
INSERT INTO BANKING_DQ_DB.DQ_MONITORING.DQ_RULE_CONFIG
(RULE_ID, RULE_NAME, RULE_TYPE, FREQUENCY, CRITICALITY, DB_NAME, TABLE_NM, COLUMN_NM, RULE_DESCRIPTION, RULE_SQL, THRESHOLD_VALUE, RULE_DIMENSION, IS_ACTIVE)
SELECT 'BR-T01','BRANCHES_NULL_COUNT_BRANCH_ID','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','BRANCHES','BRANCH_ID','NULL count on PK BRANCH_ID','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES WHERE BRANCH_ID IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'BR-T02','BRANCHES_DUPLICATE_COUNT_BRANCH_ID','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','BRANCHES','BRANCH_ID','Duplicate count on PK BRANCH_ID','SELECT COUNT(*) - COUNT(DISTINCT BRANCH_ID) FROM BANKING_DQ_DB.RAW.BRANCHES',0,PARSE_JSON('["uniqueness"]'),TRUE
UNION ALL SELECT 'BR-T03','BRANCHES_NULL_COUNT_BRANCH_NAME','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','BRANCHES','BRANCH_NAME','NULL count on BRANCH_NAME','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES WHERE BRANCH_NAME IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'BR-T04','BRANCHES_NULL_COUNT_IFSC_CODE','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','BRANCHES','IFSC_CODE','NULL count on IFSC_CODE','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES WHERE IFSC_CODE IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'BR-T05','BRANCHES_ROW_COUNT','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','BRANCHES',NULL,'Row count volume monitoring','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'BR-T06','BRANCHES_DUPLICATE_COUNT_IFSC','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','BRANCHES','IFSC_CODE','Duplicate count on IFSC_CODE','SELECT COUNT(*) - COUNT(DISTINCT IFSC_CODE) FROM BANKING_DQ_DB.RAW.BRANCHES',0,PARSE_JSON('["uniqueness"]'),TRUE
UNION ALL SELECT 'BR-B01','BRANCHES_IFSC_FORMAT','CUSTOM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','BRANCHES','IFSC_CODE','IFSC format: 4 alpha + 0 + 6 alphanum','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES WHERE IFSC_CODE IS NOT NULL AND NOT RLIKE(IFSC_CODE, ''^[A-Z]{4}0[A-Z0-9]{6}$'')',0,PARSE_JSON('["validity"]'),TRUE
UNION ALL SELECT 'BR-B02','BRANCHES_STATE_ACCEPTED_VALUES','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','BRANCHES','STATE','STATE must not be NULL or empty','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.BRANCHES WHERE STATE IS NULL OR LENGTH(TRIM(STATE)) = 0',0,PARSE_JSON('["completeness"]'),TRUE;

