UNION ALL SELECT 'CU-T03','CUSTOMERS_NULL_COUNT_EMAIL','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','EMAIL','NULL count on EMAIL','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE EMAIL IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'CU-T04','CUSTOMERS_DUPLICATE_COUNT_EMAIL','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','EMAIL','Duplicate count on EMAIL','SELECT COUNT(*) - COUNT(DISTINCT EMAIL) FROM BANKING_DQ_DB.RAW.CUSTOMERS',0,PARSE_JSON('["uniqueness"]'),TRUE
UNION ALL SELECT 'CU-T05','CUSTOMERS_NULL_COUNT_PHONE','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','CUSTOMERS','PHONE','NULL count on PHONE','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE PHONE IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'CU-T06','CUSTOMERS_NULL_COUNT_DOB','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','CUSTOMERS','DATE_OF_BIRTH','NULL count on DATE_OF_BIRTH','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE DATE_OF_BIRTH IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'CU-T07','CUSTOMERS_ROW_COUNT','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','CUSTOMERS',NULL,'Row count volume monitoring','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'CU-B01','CUSTOMERS_EMAIL_FORMAT','CUSTOM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','EMAIL','EMAIL must contain @ and .','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE EMAIL IS NOT NULL AND EMAIL NOT LIKE ''%_@_%.__%''',0,PARSE_JSON('["validity"]'),TRUE
UNION ALL SELECT 'CU-B02','CUSTOMERS_KYC_ACCEPTED_VALUES','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','KYC_STATUS','KYC_STATUS in (VERIFIED,PENDING,REJECTED)','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE KYC_STATUS NOT IN (''VERIFIED'',''PENDING'',''REJECTED'')',0,PARSE_JSON('["consistency"]'),TRUE
UNION ALL SELECT 'CU-B03','CUSTOMERS_RISK_ACCEPTED_VALUES','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','RISK_CATEGORY','RISK_CATEGORY in (LOW,MEDIUM,HIGH)','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE RISK_CATEGORY NOT IN (''LOW'',''MEDIUM'',''HIGH'')',0,PARSE_JSON('["validity"]'),TRUE
UNION ALL SELECT 'CU-B04','CUSTOMERS_DOB_RANGE','BUSINESS_RULE','ON_DEMAND','MEDIUM','BANKING_DQ_DB.RAW','CUSTOMERS','DATE_OF_BIRTH','Age must be 18-120 years','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE DATE_OF_BIRTH IS NOT NULL AND (DATEDIFF(YEAR,DATE_OF_BIRTH,CURRENT_DATE())<18 OR DATEDIFF(YEAR,DATE_OF_BIRTH,CURRENT_DATE())>120)',0,PARSE_JSON('["accuracy"]'),TRUE
UNION ALL SELECT 'CU-B05','CUSTOMERS_BRANCH_FK','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','CUSTOMERS','BRANCH_ID','BRANCH_ID must exist in BRANCHES','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS C LEFT JOIN BANKING_DQ_DB.RAW.BRANCHES B ON C.BRANCH_ID=B.BRANCH_ID WHERE B.BRANCH_ID IS NULL',0,PARSE_JSON('["integrity"]'),TRUE
UNION ALL SELECT 'CU-B06','CUSTOMERS_PHONE_FORMAT','CUSTOM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','CUSTOMERS','PHONE','PHONE must have 10+ digits','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.CUSTOMERS WHERE PHONE IS NOT NULL AND LENGTH(REGEXP_REPLACE(PHONE, ''[^0-9]'', '''')) < 10',0,PARSE_JSON('["validity"]'),TRUE;

