UNION ALL SELECT 'LA-T04','LOANS_NULL_COUNT_REQUESTED_AMT','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','REQUESTED_AMOUNT','NULL count on REQUESTED_AMOUNT','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE REQUESTED_AMOUNT IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'LA-T05','LOANS_NULL_COUNT_CREDIT_SCORE','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','CREDIT_SCORE','NULL count on CREDIT_SCORE','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE CREDIT_SCORE IS NULL',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'LA-T06','LOANS_ROW_COUNT','SYSTEM_DMF','TRIGGER_ON_CHANGES','MEDIUM','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS',NULL,'Row count volume monitoring','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS',0,PARSE_JSON('["completeness"]'),TRUE
UNION ALL SELECT 'LA-B01','LOANS_REQUESTED_AMT_POSITIVE','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','REQUESTED_AMOUNT','REQUESTED_AMOUNT must be > 0','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE REQUESTED_AMOUNT <= 0',0,PARSE_JSON('["accuracy"]'),TRUE
UNION ALL SELECT 'LA-B02','LOANS_APPROVED_LTE_REQUESTED','CUSTOM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','APPROVED_AMOUNT','APPROVED_AMOUNT <= REQUESTED_AMOUNT','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE APPROVED_AMOUNT IS NOT NULL AND REQUESTED_AMOUNT IS NOT NULL AND APPROVED_AMOUNT > REQUESTED_AMOUNT',0,PARSE_JSON('["accuracy"]'),TRUE
