UNION ALL SELECT 'LA-B06','LOANS_APPROVED_HAS_AMOUNT','CUSTOM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','APPROVED_AMOUNT','APPROVED status must have APPROVED_AMOUNT','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE APPLICATION_STATUS = ''APPROVED'' AND APPROVED_AMOUNT IS NULL',0,PARSE_JSON('["consistency"]'),TRUE
UNION ALL SELECT 'LA-B07','LOANS_CUSTOMER_FK','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','CUSTOMER_ID','CUSTOMER_ID must exist in CUSTOMERS','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS L LEFT JOIN BANKING_DQ_DB.RAW.CUSTOMERS C ON L.CUSTOMER_ID=C.CUSTOMER_ID WHERE C.CUSTOMER_ID IS NULL',0,PARSE_JSON('["integrity"]'),TRUE
UNION ALL SELECT 'LA-B08','LOANS_BRANCH_FK','SYSTEM_DMF','TRIGGER_ON_CHANGES','HIGH','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','BRANCH_ID','BRANCH_ID must exist in BRANCHES','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS L LEFT JOIN BANKING_DQ_DB.RAW.BRANCHES B ON L.BRANCH_ID=B.BRANCH_ID WHERE B.BRANCH_ID IS NULL',0,PARSE_JSON('["integrity"]'),TRUE
UNION ALL SELECT 'LA-B09','LOANS_DATE_NOT_FUTURE','BUSINESS_RULE','ON_DEMAND','MEDIUM','BANKING_DQ_DB.RAW','LOAN_APPLICATIONS','APPLICATION_DATE','APPLICATION_DATE must not be future','SELECT COUNT(*) FROM BANKING_DQ_DB.RAW.LOAN_APPLICATIONS WHERE APPLICATION_DATE > CURRENT_DATE()',0,PARSE_JSON('["accuracy"]'),TRUE;

