SELECT TABLE_NM, RULE_TYPE, CRITICALITY, COUNT(*) AS RULE_COUNT
FROM BANKING_DQ_DB.DQ_MONITORING.DQ_RULE_CONFIG
GROUP BY TABLE_NM, RULE_TYPE, CRITICALITY
ORDER BY TABLE_NM, RULE_TYPE, CRITICALITY;

